const recoCarousel=document.querySelector("[data-reco-carousel]");if(recoCarousel){const e=Array.from(recoCarousel.querySelectorAll("[data-reco-slide]"));if(e.length>1){let s=e.findIndex(i=>i.classList.contains("is-visible"));s===-1&&(s=0,e[0].classList.add("is-visible")),setInterval(()=>{e[s].classList.remove("is-visible"),s=(s+1)%e.length,e[s].classList.add("is-visible")},3e3)}}
